import { describe, expect, test } from "vitest";
import { Command } from "commander";

import { registerSetupCommand } from "../commands/setup.js";
import { registerRemoveCommand } from "../commands/remove.js";
import { ALL_AGENT_NAMES, getAgent } from "../setup/agents.js";

function registeredLongOptions(command: Command): string[] {
  return command.options.flatMap((option) => (option.long ? [option.long] : []));
}

describe("agent command registry", () => {
  test.each([
    ["setup", registerSetupCommand],
    ["remove", registerRemoveCommand],
  ] as const)("%s exposes every registered agent flag", (commandName, register) => {
    const program = new Command();
    register(program);

    const command = program.commands.find((candidate) => candidate.name() === commandName);
    expect(command).toBeDefined();
    expect(registeredLongOptions(command!)).toEqual(
      expect.arrayContaining(ALL_AGENT_NAMES.map((name) => `--${name}`))
    );
  });

  test("file-specific rule formatting belongs to the agent policy", () => {
    const cursorRule = getAgent("cursor").rule;
    expect(cursorRule.kind).toBe("file");
    if (cursorRule.kind === "file") {
      expect(cursorRule.contentPrefix).toBe(`---\nalwaysApply: true\n---\n\n`);
    }
  });
});

import { describe, test, expect, vi, beforeEach, afterEach } from "vitest";
import { Command } from "commander";

const mockGetValidAccessToken = vi.fn();
const mockClearTokens = vi.fn();
const mockSaveTokens = vi.fn();
const mockStartDeviceAuthorization = vi.fn();
const mockPollDeviceToken = vi.fn();

vi.mock("../utils/auth.js", async (importOriginal) => {
  const original = await importOriginal<typeof import("../utils/auth.js")>();
  return {
    ...original,
    getValidAccessToken: (...args: unknown[]) => mockGetValidAccessToken(...args),
    clearTokens: (...args: unknown[]) => mockClearTokens(...args),
    saveTokens: (...args: unknown[]) => mockSaveTokens(...args),
    startDeviceAuthorization: (...args: unknown[]) => mockStartDeviceAuthorization(...args),
    pollDeviceToken: (...args: unknown[]) => mockPollDeviceToken(...args),
  };
});

vi.mock("../utils/tracking.js", () => ({
  trackEvent: vi.fn(),
}));

const mockSpinner = {
  start: vi.fn().mockReturnThis(),
  stop: vi.fn().mockReturnThis(),
  succeed: vi.fn().mockReturnThis(),
  fail: vi.fn().mockReturnThis(),
  text: "",
};
vi.mock("ora", () => ({ default: () => mockSpinner }));

const mockOpen = vi.fn().mockResolvedValue(undefined);
vi.mock("open", () => ({ default: (...args: unknown[]) => mockOpen(...args) }));

vi.mock("../constants.js", () => ({ CLI_CLIENT_ID: "test-client-id" }));
vi.mock("../utils/api.js", () => ({ getBaseUrl: () => "https://test.context7.com" }));

import { registerAuthCommands, performLogin } from "../commands/auth.js";
import { trackEvent } from "../utils/tracking.js";

let logOutput: string[];
let errorOutput: string[];
let originalExit: typeof process.exit;

beforeEach(() => {
  vi.clearAllMocks();
  logOutput = [];
  errorOutput = [];
  vi.spyOn(console, "log").mockImplementation((...args: unknown[]) => {
    logOutput.push(args.join(" "));
  });
  vi.spyOn(console, "error").mockImplementation((...args: unknown[]) => {
    errorOutput.push(args.join(" "));
  });
  originalExit = process.exit;
  process.exit = vi.fn() as never;

  vi.stubGlobal(
    "fetch",
    vi.fn(() => {
      throw new Error("fetch not mocked");
    })
  );
});

afterEach(() => {
  process.exit = originalExit;
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

async function runCommand(...args: string[]): Promise<void> {
  const program = new Command();
  program.exitOverride(); // throw instead of process.exit on commander errors
  registerAuthCommands(program);
  await program.parseAsync(["node", "test", ...args]);
}

describe("login command", () => {
  test("skips login when valid token exists", async () => {
    mockGetValidAccessToken.mockResolvedValue("existing-token");
    await runCommand("login");
    expect(logOutput.some((l) => l.includes("already logged in"))).toBe(true);
  });

  test("tracks login event", async () => {
    mockGetValidAccessToken.mockResolvedValue("existing-token");
    await runCommand("login");
    expect(trackEvent).toHaveBeenCalledWith("command", { name: "login" });
  });

  test("calls process.exit(1) when login fails", async () => {
    mockGetValidAccessToken.mockResolvedValue(undefined);
    mockClearTokens.mockReturnValue(false);
    mockStartDeviceAuthorization.mockRejectedValue(new Error("network down"));

    await runCommand("login").catch(() => {});
    expect(process.exit).toHaveBeenCalledWith(1);
  });
});

describe("logout command", () => {
  test("logs success when tokens were cleared", async () => {
    mockClearTokens.mockReturnValue(true);
    await runCommand("logout");
    expect(logOutput.some((l) => l.includes("Logged out successfully"))).toBe(true);
  });

  test("logs 'not logged in' when no tokens existed", async () => {
    mockClearTokens.mockReturnValue(false);
    await runCommand("logout");
    expect(logOutput.some((l) => l.includes("You are not logged in"))).toBe(true);
  });

  test("tracks logout event", async () => {
    mockClearTokens.mockReturnValue(false);
    await runCommand("logout");
    expect(trackEvent).toHaveBeenCalledWith("command", { name: "logout" });
  });
});

describe("whoami command", () => {
  test("shows 'Not logged in' when no valid token", async () => {
    mockGetValidAccessToken.mockResolvedValue(undefined);
    await runCommand("whoami");
    expect(logOutput.some((l) => l.includes("Not logged in"))).toBe(true);
  });

  test("fetches and displays user info when logged in", async () => {
    mockGetValidAccessToken.mockResolvedValue("valid-token");
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: true,
        json: () =>
          Promise.resolve({
            success: true,
            name: "Test User",
            email: "test@example.com",
            teamspace: null,
          }),
      })
    );

    await runCommand("whoami");
    expect(logOutput.some((l) => l.includes("Logged in"))).toBe(true);
    expect(logOutput.some((l) => l.includes("Test User"))).toBe(true);
    expect(logOutput.some((l) => l.includes("test@example.com"))).toBe(true);
  });

  test("reports API-key authentication without calling the dashboard", async () => {
    mockGetValidAccessToken.mockResolvedValue("ctx7sk-valid-key");
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);

    await runCommand("whoami");

    expect(logOutput.some((l) => l.includes("Logged in"))).toBe(true);
    expect(logOutput).toHaveLength(1);
    expect(logOutput.some((l) => l.includes("Session may be expired"))).toBe(false);
    expect(fetchMock).not.toHaveBeenCalled();
  });

  test("shows logout before login when the server rejects a saved session", async () => {
    mockGetValidAccessToken.mockResolvedValue("valid-token");
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: false,
        status: 401,
        json: () => Promise.reject(new Error("fail")),
      })
    );

    await runCommand("whoami");
    expect(logOutput.join("\n")).toMatch(/ctx7 logout.*ctx7 login/);
  });

  test.each([403, 500])("does not recommend logout for HTTP %i", async (status) => {
    mockGetValidAccessToken.mockResolvedValue("valid-token");
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response(null, { status })));

    await runCommand("whoami");

    expect(logOutput.join("\n")).toContain("Could not verify your session");
    expect(logOutput.join("\n")).not.toMatch(/ctx7 logout|ctx7 login/);
  });

  test("does not recommend logout when the identity request fails", async () => {
    mockGetValidAccessToken.mockResolvedValue("valid-token");
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(new TypeError("fetch failed")));

    await runCommand("whoami");

    expect(logOutput.join("\n")).toContain("Could not verify your session");
    expect(logOutput.join("\n")).not.toMatch(/ctx7 logout|ctx7 login/);
  });

  test("does not recommend logout for an invalid identity response", async () => {
    mockGetValidAccessToken.mockResolvedValue("valid-token");
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response("{")));

    await runCommand("whoami");

    expect(logOutput.join("\n")).toContain("Could not verify your session");
    expect(logOutput.join("\n")).not.toMatch(/ctx7 logout|ctx7 login/);
  });

  test("tracks whoami event", async () => {
    mockGetValidAccessToken.mockResolvedValue(undefined);
    await runCommand("whoami");
    expect(trackEvent).toHaveBeenCalledWith("command", { name: "whoami" });
  });
});

describe("performLogin", () => {
  const authorization = {
    device_code: "dc",
    user_code: "ABCD-EFGH",
    verification_uri: "https://t.example/oauth/device",
    verification_uri_complete: "https://t.example/oauth/device?user_code=ABCD-EFGH",
    expires_in: 600,
    interval: 0, // 0ms poll cadence so tests don't need fake timers
  };

  beforeEach(() => {
    // Quiet whoami so announceIdentity falls back without polluting stdout.
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({ ok: false, json: () => Promise.resolve({}) })
    );
  });

  test("returns access_token on approved", async () => {
    mockStartDeviceAuthorization.mockResolvedValue(authorization);
    mockPollDeviceToken.mockResolvedValue({
      status: "approved",
      tokens: { access_token: "ctx7sk-x", token_type: "bearer" },
    });

    const result = await performLogin(false);
    expect(result).toBe("ctx7sk-x");
    expect(mockSaveTokens).toHaveBeenCalledWith({
      access_token: "ctx7sk-x",
      token_type: "bearer",
    });
    expect(fetch).not.toHaveBeenCalled();
    expect(mockSpinner.succeed).toHaveBeenCalledWith(expect.stringContaining("API key"));
  });

  test("returns null on denied", async () => {
    mockStartDeviceAuthorization.mockResolvedValue(authorization);
    mockPollDeviceToken.mockResolvedValue({ status: "denied" });

    expect(await performLogin(false)).toBeNull();
    expect(mockSaveTokens).not.toHaveBeenCalled();
  });

  test("returns null on expired", async () => {
    mockStartDeviceAuthorization.mockResolvedValue(authorization);
    mockPollDeviceToken.mockResolvedValue({ status: "expired" });

    expect(await performLogin(false)).toBeNull();
    expect(mockSaveTokens).not.toHaveBeenCalled();
  });

  test("keeps polling on transient errors and applies backoff (RFC 8628 §3.5)", async () => {
    vi.useFakeTimers();
    try {
      mockStartDeviceAuthorization.mockResolvedValue(authorization);
      mockPollDeviceToken
        .mockResolvedValueOnce({ status: "transient", errorMessage: "ECONN" })
        .mockResolvedValueOnce({ status: "pending" })
        .mockResolvedValueOnce({
          status: "approved",
          tokens: { access_token: "t", token_type: "bearer" },
        });

      const pending = performLogin(false);
      // transient bumps the interval by 5s (mirroring slow_down), so the
      // 2nd and 3rd polls each need a 5s wait. Advance enough to cover both.
      await vi.advanceTimersByTimeAsync(11_000);
      const result = await pending;
      expect(result).toBe("t");
      expect(mockPollDeviceToken).toHaveBeenCalledTimes(3);
    } finally {
      vi.useRealTimers();
    }
  });

  test("backs off polling cadence when slow_down is returned", async () => {
    vi.useFakeTimers();
    try {
      mockStartDeviceAuthorization.mockResolvedValue(authorization);
      mockPollDeviceToken.mockResolvedValueOnce({ status: "slow_down" }).mockResolvedValueOnce({
        status: "approved",
        tokens: { access_token: "t", token_type: "bearer" },
      });

      const pending = performLogin(false);
      // First poll fires after the initial 0ms interval; slow_down then
      // bumps the interval by 5000ms before the second poll.
      await vi.advanceTimersByTimeAsync(5500);
      const result = await pending;
      expect(result).toBe("t");
      expect(mockPollDeviceToken).toHaveBeenCalledTimes(2);
    } finally {
      vi.useRealTimers();
    }
  });

  test("returns null when start request throws", async () => {
    mockStartDeviceAuthorization.mockRejectedValue(new Error("network down"));

    expect(await performLogin(false)).toBeNull();
    expect(mockPollDeviceToken).not.toHaveBeenCalled();
  });

  test("opens verification_uri_complete when openBrowser=true and stdin is non-TTY", async () => {
    const originalIsTTY = process.stdin.isTTY;
    Object.defineProperty(process.stdin, "isTTY", { value: false, configurable: true });
    try {
      mockStartDeviceAuthorization.mockResolvedValue(authorization);
      mockPollDeviceToken.mockResolvedValue({
        status: "approved",
        tokens: { access_token: "t", token_type: "bearer" },
      });

      await performLogin(true);
      expect(mockOpen).toHaveBeenCalledWith(authorization.verification_uri_complete);
    } finally {
      Object.defineProperty(process.stdin, "isTTY", { value: originalIsTTY, configurable: true });
    }
  });

  test("skips opening a browser when openBrowser=false", async () => {
    mockStartDeviceAuthorization.mockResolvedValue(authorization);
    mockPollDeviceToken.mockResolvedValue({
      status: "approved",
      tokens: { access_token: "t", token_type: "bearer" },
    });

    await performLogin(false);
    expect(mockOpen).not.toHaveBeenCalled();
  });

  test("defaults poll interval to 5s when server omits it (RFC 8628 §3.2)", async () => {
    vi.useFakeTimers();
    try {
      mockStartDeviceAuthorization.mockResolvedValue({ ...authorization, interval: undefined });
      mockPollDeviceToken.mockResolvedValueOnce({ status: "pending" }).mockResolvedValueOnce({
        status: "approved",
        tokens: { access_token: "t", token_type: "bearer" },
      });

      const pending = performLogin(false);
      // Two 5s polls.
      await vi.advanceTimersByTimeAsync(11_000);
      const result = await pending;
      expect(result).toBe("t");
      expect(mockPollDeviceToken).toHaveBeenCalledTimes(2);
    } finally {
      vi.useRealTimers();
    }
  });
});

import { describe, test, expect, vi, beforeEach, afterEach } from "vitest";

vi.mock("fs", () => {
  const fns = {
    existsSync: vi.fn(),
    mkdirSync: vi.fn(),
    writeFileSync: vi.fn(),
    readFileSync: vi.fn(),
    unlinkSync: vi.fn(),
    renameSync: vi.fn(),
    chmodSync: vi.fn(),
  };
  return { ...fns, default: fns };
});

vi.mock("../constants.js", () => ({ CLI_CLIENT_ID: "test-client-id" }));
vi.mock("../utils/api.js", () => ({ getBaseUrl: () => "https://test.context7.com" }));

import * as fs from "fs";
import {
  saveTokens,
  loadTokens,
  clearTokens,
  isTokenExpired,
  isContext7ApiKey,
  getValidAccessToken,
  startDeviceAuthorization,
  pollDeviceToken,
  type TokenData,
} from "../utils/auth.js";

const mfs = vi.mocked(fs);
const CREDENTIALS_PATH = "/fake-home/.config/context7/credentials.json";
const LEGACY_CREDENTIALS_PATH = "/fake-home/.context7/credentials.json";
const CONFIG_DIR_PATH = "/fake-home/.config/context7";

beforeEach(() => {
  vi.clearAllMocks();
  // os.homedir() reads $HOME first on POSIX, so stubbing the env var pins the
  // home directory deterministically without mocking the `os` builtin (which
  // resolves unreliably across Node versions / worker pooling in CI).
  vi.stubEnv("HOME", "/fake-home");
  vi.stubEnv("XDG_CONFIG_HOME", undefined);
  vi.stubEnv("XDG_STATE_HOME", undefined);
  vi.stubEnv("XDG_CACHE_HOME", undefined);
  vi.stubGlobal(
    "fetch",
    vi.fn(() => {
      throw new Error("fetch not mocked for this test");
    })
  );
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.unstubAllEnvs();
});

describe("saveTokens", () => {
  test("creates config directory if it does not exist", () => {
    mfs.existsSync.mockReturnValue(false);
    saveTokens({ access_token: "tok", token_type: "bearer" });
    expect(mfs.mkdirSync).toHaveBeenCalledWith(CONFIG_DIR_PATH, { recursive: true, mode: 0o700 });
  });

  test("skips directory creation if it already exists", () => {
    mfs.existsSync.mockReturnValue(true);
    saveTokens({ access_token: "tok", token_type: "bearer" });
    expect(mfs.mkdirSync).not.toHaveBeenCalled();
  });

  test("writes credentials file with 0o600 permissions", () => {
    mfs.existsSync.mockReturnValue(true);
    saveTokens({ access_token: "tok", token_type: "bearer" });
    expect(mfs.writeFileSync).toHaveBeenCalledWith(CREDENTIALS_PATH, expect.any(String), {
      mode: 0o600,
    });
  });

  test("enforces 0o600 even when the credentials file already exists", () => {
    // writeFileSync's mode is ignored for an existing file, so chmod must run.
    mfs.existsSync.mockReturnValue(true);
    saveTokens({ access_token: "tok", token_type: "bearer" });
    expect(mfs.chmodSync).toHaveBeenCalledWith(CREDENTIALS_PATH, 0o600);
  });

  test("honors XDG_CONFIG_HOME for credentials", () => {
    vi.stubEnv("XDG_CONFIG_HOME", "/custom-config");
    mfs.existsSync.mockReturnValue(false);
    saveTokens({ access_token: "tok", token_type: "bearer" });

    expect(mfs.mkdirSync).toHaveBeenCalledWith("/custom-config/context7", {
      recursive: true,
      mode: 0o700,
    });
    expect(mfs.writeFileSync).toHaveBeenCalledWith(
      "/custom-config/context7/credentials.json",
      expect.any(String),
      { mode: 0o600 }
    );
  });

  test("computes expires_at from expires_in when expires_at is absent", () => {
    mfs.existsSync.mockReturnValue(true);
    const now = 1000000;
    vi.spyOn(Date, "now").mockReturnValue(now);
    saveTokens({ access_token: "tok", token_type: "bearer", expires_in: 3600 });
    const written = JSON.parse(mfs.writeFileSync.mock.calls[0][1] as string);
    expect(written.expires_at).toBe(now + 3600 * 1000);
  });

  test("preserves existing expires_at if already set", () => {
    mfs.existsSync.mockReturnValue(true);
    saveTokens({ access_token: "tok", token_type: "bearer", expires_at: 999, expires_in: 3600 });
    const written = JSON.parse(mfs.writeFileSync.mock.calls[0][1] as string);
    expect(written.expires_at).toBe(999);
  });
});

describe("loadTokens", () => {
  test("returns null when credentials file does not exist", () => {
    mfs.existsSync.mockReturnValue(false);
    expect(loadTokens()).toBeNull();
  });

  test("returns parsed TokenData when file exists", () => {
    const tokens: TokenData = { access_token: "tok", token_type: "bearer" };
    mfs.existsSync.mockReturnValue(true);
    mfs.readFileSync.mockReturnValue(JSON.stringify(tokens));
    expect(loadTokens()).toEqual(tokens);
  });

  test("migrates credentials from the legacy ~/.context7 path before reading", () => {
    const tokens: TokenData = { access_token: "tok", token_type: "bearer" };
    let migrated = false;
    mfs.existsSync.mockImplementation((filePath) =>
      filePath === CREDENTIALS_PATH
        ? migrated
        : filePath === LEGACY_CREDENTIALS_PATH || filePath === CONFIG_DIR_PATH
    );
    mfs.renameSync.mockImplementation(() => {
      migrated = true;
    });
    mfs.readFileSync.mockReturnValue(JSON.stringify(tokens));

    expect(loadTokens()).toEqual(tokens);
    expect(mfs.renameSync).toHaveBeenCalledWith(LEGACY_CREDENTIALS_PATH, CREDENTIALS_PATH);
    // rename preserves the legacy mode, so migration must re-assert 0o600.
    expect(mfs.chmodSync).toHaveBeenCalledWith(CREDENTIALS_PATH, 0o600);
    expect(mfs.readFileSync).toHaveBeenCalledWith(CREDENTIALS_PATH, "utf-8");
  });

  test("returns null on malformed JSON", () => {
    mfs.existsSync.mockReturnValue(true);
    mfs.readFileSync.mockReturnValue("not json");
    expect(loadTokens()).toBeNull();
  });

  test("falls back to the legacy file (no throw) when migration fails", () => {
    const tokens: TokenData = { access_token: "tok", token_type: "bearer" };
    // Only the legacy file exists; the rename fails (e.g. EXDEV / EACCES).
    mfs.existsSync.mockImplementation((filePath) => filePath === LEGACY_CREDENTIALS_PATH);
    mfs.renameSync.mockImplementation(() => {
      throw new Error("EXDEV: cross-device link not permitted");
    });
    mfs.readFileSync.mockReturnValue(JSON.stringify(tokens));

    expect(() => loadTokens()).not.toThrow();
    expect(loadTokens()).toEqual(tokens);
    expect(mfs.readFileSync).toHaveBeenCalledWith(LEGACY_CREDENTIALS_PATH, "utf-8");
  });
});

